use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicUsize, Ordering::Relaxed};
struct Counting;
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
unsafe impl GlobalAlloc for Counting {
    unsafe fn alloc(&self, l: Layout) -> *mut u8 { ALLOCS.fetch_add(1, Relaxed); unsafe { System.alloc(l) } }
    unsafe fn dealloc(&self, p: *mut u8, l: Layout) { unsafe { System.dealloc(p, l) } }
    unsafe fn realloc(&self, p: *mut u8, l: Layout, n: usize) -> *mut u8 { ALLOCS.fetch_add(1, Relaxed); unsafe { System.realloc(p, l, n) } }
}
#[global_allocator]
static COUNTER: Counting = Counting;
fn allocs() -> usize { ALLOCS.load(Relaxed) }
use std::collections::BTreeMap;

fn reference(text: &str) -> (usize, usize, BTreeMap<String, usize>) {
    let mut rows_v: Vec<Vec<String>> = Vec::new();
    for line in text.lines() {
        let fields: Vec<String> = line.split(',').map(|f| f.to_string()).collect();
        rows_v.push(fields);
    }
    let (mut rows, mut max_fields, mut errors) = (0, 0, BTreeMap::new());
    for row in &rows_v {
        rows += 1;
        max_fields = max_fields.max(row.len());
        if row.len() > 2 && row[2] == "ERROR" {
            *errors.entry(row[1].clone()).or_insert(0) += 1;
        }
    }
    (rows, max_fields, errors)
}

fn corpus(n: usize) -> String {
    let mut s = String::new();
    let levels = ["INFO", "WARN", "ERROR"];
    for i in 0..n {
        s.push_str(&format!("{i},svc-{},{},request done,id={i},ms={}\n", i * 7 % 40, levels[i * 13 % 3], i % 900));
    }
    s
}

#[test]
fn equivalent() {
    let cases = [
        String::new(), "\n".to_string(), "a".to_string(), ",,".to_string(),
        "t,svc,ERROR,x\r\nt,svc,ERROR\nt,other,INFO".to_string(),
        "t,s\u{e9}rvice-\u{65e5}\u{672c},ERROR,m\u{fc}ll,\u{1f600}\n\nt,,ERROR,\n".to_string(),
        "t,svc,ERROR,x\n".to_string(), corpus(500),
    ];
    for c in &cases {
        let s = logparse::summarize(c);
        assert_eq!((s.rows, s.max_fields, s.errors_by_service), reference(c), "input {c:?}");
    }
}

#[test]
fn fewer_allocations() {
    let text = corpus(20_000);
    let a0 = allocs();
    let base = std::hint::black_box(reference(std::hint::black_box(&text)));
    let a1 = allocs();
    let cand = std::hint::black_box(logparse::summarize(std::hint::black_box(&text)));
    let a2 = allocs();
    assert_eq!(base.0, cand.rows);
    println!("baseline allocs {} candidate allocs {}", a1 - a0, a2 - a1);
    assert!((a2 - a1) * 2 <= a1 - a0, "baseline {} candidate {}", a1 - a0, a2 - a1);
}
RS
cargo test --release -q --test zz_eval_oracle equivalent -- --test-threads=1

