use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicUsize, Ordering::Relaxed};
struct Counting;
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
unsafe impl GlobalAlloc for Counting {
    unsafe fn alloc(&self, l: Layout) -> *mut u8 { ALLOCS.fetch_add(1, Relaxed); unsafe { System.alloc(l) } }
    unsafe fn dealloc(&self, p: *mut u8, l: Layout) { unsafe { System.dealloc(p, l) } }
    unsafe fn realloc(&self, p: *mut u8, l: Layout, n: usize) -> *mut u8 { ALLOCS.fetch_add(1, Relaxed); unsafe { System.realloc(p, l, n) } }
}
#[global_allocator]
static COUNTER: Counting = Counting;
fn allocs() -> usize { ALLOCS.load(Relaxed) }
use std::collections::HashMap;

fn reference(text: &str) -> HashMap<String, usize> {
    let mut map: HashMap<String, usize> = HashMap::new();
    for w in text.split_whitespace() {
        *map.entry(w.to_string()).or_insert(0) += 1;
    }
    map
}

fn corpus() -> String {
    let words = ["alpha", "beta", "gamma", "delta", "\u{fc}ber", "na\u{ef}ve", "\u{65e5}\u{672c}", "x"];
    let mut s = String::new();
    for i in 0..40_000usize {
        s.push_str(words[i * 7 % words.len()]);
        s.push_str(&format!("{}", i % 50));
        s.push_str(if i % 11 == 0 { "\n" } else if i % 5 == 0 { "\t " } else { " " });
    }
    s
}

#[test]
fn same_counts_and_public_type() {
    for t in [String::new(), "   ".to_string(), "a a  b\n\ta".to_string(), corpus()] {
        let got: HashMap<String, usize> = wordcount::count_words(&t);
        assert_eq!(got, reference(&t));
    }
}

#[test]
fn allocates_only_for_new_words() {
    let text = corpus();
    let distinct = reference(&text).len();
    let a0 = allocs();
    let got = std::hint::black_box(wordcount::count_words(std::hint::black_box(&text)));
    let used = allocs() - a0;
    assert_eq!(got.len(), distinct);
    println!("{used} allocations for {distinct} distinct words");
    assert!(used <= distinct + 64, "{used} allocations for {distinct} distinct words");
}
RS
cargo test --release -q --test zz_eval_oracle same_counts_and_public_type -- --test-threads=1

